async def act(page):
    # Navigate directly to the New Shopping Cart Price Rule page to avoid clicking a link
    # that would navigate away mid-script. Using a relative goto as allowed.
    await page.goto("/index.php/admin/promo_quote/new/")
    await page.wait_for_load_state("networkidle")

    # Fill Rule Name (try common accessible names)
    try:
        name_box = page.get_by_role("textbox", name="Rule Name")
        if await name_box.count() == 0:
            name_box = page.get_by_role("textbox", name="Name")
        if await name_box.count() > 0:
            await name_box.first().fill("Mother's Day Sale")
    except Exception:
        pass

    # Fill Description (textbox/textarea fallback)
    try:
        desc = page.get_by_role("textbox", name="Description")
        if await desc.count() == 0:
            all_text = page.get_by_role("textbox")
            if await all_text.count() > 1:
                desc = all_text.nth(1)
        if desc and (await desc.count()) > 0:
            await desc.first().fill("$15 discount on checkout for all customers. Mother's Day promotion.")
    except Exception:
        pass

    # Ensure rule is Active (try comboboxes named Status or Active)
    try:
        status_combo = page.get_by_role("combobox", name="Status")
        if await status_combo.count() == 0:
            status_combo = page.get_by_role("combobox", name="Active")
        if await status_combo.count() > 0:
            # prefer selecting by visible label
            try:
                await status_combo.first().select_option(label="Active")
            except Exception:
                try:
                    await status_combo.first().select_option(label="Yes")
                except Exception:
                    try:
                        await status_combo.first().select_option(value="1")
                    except Exception:
                        pass
    except Exception:
        pass

    # Check all checkboxes so the rule applies to all Websites and Customer Groups
    try:
        boxes = page.get_by_role("checkbox")
        total = await boxes.count()
        for i in range(total):
            try:
                await boxes.nth(i).check()
            except Exception:
                pass
    except Exception:
        pass

    # Set Apply to a fixed cart discount (combobox names: Apply / Apply To / Action)
    try:
        apply_combo = page.get_by_role("combobox", name="Apply")
        if await apply_combo.count() == 0:
            apply_combo = page.get_by_role("combobox", name="Apply To")
        if await apply_combo.count() == 0:
            apply_combo = page.get_by_role("combobox", name="Action")
        if await apply_combo.count() > 0:
            # try typical Magento labels first, then fallback to value
            tried = False
            for label in [
                "Fixed amount discount for whole cart",
                "Fixed amount",
                "Fixed",
            ]:
                try:
                    await apply_combo.first().select_option(label=label)
                    tried = True
                    break
                except Exception:
                    pass
            if not tried:
                try:
                    await apply_combo.first().select_option(value="cart_fixed")
                except Exception:
                    pass
    except Exception:
        pass

    # Fill Discount Amount
    try:
        discount_loc = None
        for candidate in ["Discount Amount", "Discount", "Amount"]:
            loc = page.get_by_role("textbox", name=candidate)
            if await loc.count() > 0:
                discount_loc = loc
                break
        if discount_loc is None:
            all_txt = page.get_by_role("textbox")
            total = await all_txt.count()
            for i in range(total):
                t = all_txt.nth(i)
                try:
                    nm = await t.get_attribute("name")
                    if nm and "discount" in nm.lower():
                        discount_loc = t
                        break
                except Exception:
                    pass
        if discount_loc and (await discount_loc.count()) > 0:
            await discount_loc.first().fill("15")
    except Exception:
        pass

    # Set Priority to 0 if present
    try:
        priority = page.get_by_role("textbox", name="Priority")
        if await priority.count() > 0:
            await priority.first().fill("0")
    except Exception:
        pass

    # Save the rule. This will navigate away, so make it the last action.
    try:
        save_btn = page.get_by_role("button", name="Save Rule")
        if await save_btn.count() > 0:
            await save_btn.first().click()
            await page.wait_for_load_state("networkidle")
            return
    except Exception:
        pass

    try:
        save_btn2 = page.get_by_role("button", name="Save")
        if await save_btn2.count() > 0:
            await save_btn2.first().click()
            await page.wait_for_load_state("networkidle")
            return
    except Exception:
        pass

    # If no explicit save button located, end here.
    return

